{
  "title": "修复通讯",
  "scene": "你所在的飞船出现故障，电源室的屏幕突然闪出一条未知信号。信号频繁跳跃，似乎包含了什么重要的信息。飞船内氧气即将耗尽，你必须找到办法解读这些信号，以便联系指挥中心求援。电源室里有三扇门，分别通往维修舱、核心控制室和一间不明用途的小房间。",
  "goal": "解读未知信号，联系指挥中心求援",
  "clue": "未知信号的频率和内容与电源室中的维修手册相关",
  "choices": [
    {"id": "A", "text": "前往维修舱寻找配件", "outcome": "在维修舱找到一台破损的频率调节器，但调节器缺少必要的部件。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "进入核心控制室检查系统", "outcome": "发现核心控制室的电路图上标示着关键的频率节点，但与未知信号的具体位置并不匹配。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "查看电源室小房间里的资料", "outcome": "在小房间的角落发现一本维修手册，手册中详细记录了不同频率的信号含义，以及如何进行调整。根据手册提示，成功解读了未知信号，联系上了指挥中心，但飞船燃料即将耗尽，需尽快采取行动。", "result": "success", "next": "next_level"}
  ]
}
